<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KQ Event Styling | Booking System</title><link rel="stylesheet" href="assets/styles.css"></head><body><header><strong>KQ EVENT STYLING</strong><span data-user>Loading…</span><button id="signout" hidden>Sign out</button></header><main><h1>Plan an event that feels like you.</h1><p>Book styling services online, check live availability, and track your request without a page reload.</p><p id="message" aria-live="polite"></p><section id="auth"><h2>Customer access</h2><div class="auth-grid"><form id="registerForm"><h3>Create account</h3><label>Full name<input name="name" required maxlength="80"></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="10" required></label><button>Create account</button></form><form id="loginForm"><h3>Sign in</h3><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required></label><button>Sign in</button><small>Demo admin: admin@kqstyling.test / ChangeMe123!</small></form></div></section><section id="booking" hidden><h2>Request a booking</h2><form id="bookingForm"><label>Package<select id="package_id" name="package_id"></select></label><label>Event date<input id="event_date" name="event_date" type="date" required></label><label>Available time slot<select id="slot" name="slot" required><option>Choose a date first</option></select></label><label>Venue / city<input name="venue" minlength="3" maxlength="300" required></label><label>Mobile number<input name="phone" placeholder="09XXXXXXXXX" pattern="09[0-9]{9}" required></label><label>Guests<input name="guests" type="number" min="1" max="5000" required></label><label>Distance from North Caloocan (km)<input name="distance_km" type="number" min="0" max="1000" required></label><label>Notes<textarea name="notes" maxlength="2000"></textarea></label><button>Send booking request</button></form></section><section id="records" hidden><h2>My bookings</h2><div class="scroll"><table><thead><tr><th>ID</th><th>Package</th><th>Date</th><th>Status</th><th>Total</th><th>Action</th></tr></thead><tbody id="bookingRows"></tbody></table></div></section><section id="admin" hidden><h2>Administrator dashboard</h2><div id="stats"></div><h3>Booking decisions</h3><div class="scroll"><table><thead><tr><th>ID</th><th>Customer</th><th>Package</th><th>Schedule</th><th>Status</th><th>Action</th></tr></thead><tbody id="adminRows"></tbody></table></div><h3>Change requests</h3><ul id="changeRows"></ul></section></main><script src="assets/app.js"></script></body></html>
